create or replace function lms_read_private.lock_viewer(p_proof jsonb,p_contract text,p_args jsonb) returns jsonb language plpgsql security definer set search_path='' as $fn$
declare target uuid; role_name text; managed uuid[]; teams uuid[];
begin
 if p_contract is distinct from 'dashboard' or p_args is distinct from '{}'::jsonb then raise exception 'Invalid View-As read contract';end if;
 if not view_as_private.lock_authorization(p_proof,'identity') then raise exception 'View-As access denied';end if;
 select c.target into strict target from view_as_private.contexts c where c.id=(p_proof->>'id')::uuid and c.started_at is not null and c.ended_at is null and c.expires_at>clock_timestamp();
 role_name:=view_as_private.member_role(target);
 perform 1 from public.locations l where target in(l.club_pro_member_id,l.club_pro_2_member_id) order by l.id for share;
 perform 1 from public.teams t where target in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id,t.club_pro_member_id) or exists(select 1 from public.locations l where l.id=t.home_location_id and target in(l.club_pro_member_id,l.club_pro_2_member_id)) order by t.id for share;
 select coalesce(array_agg(t.id),'{}'::uuid[]) into managed from public.teams t where role_name in('captain','club_pro','league_manager','commissioner') and (target in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id,t.club_pro_member_id) or exists(select 1 from public.locations l where l.id=t.home_location_id and target in(l.club_pro_member_id,l.club_pro_2_member_id)));
 perform 1 from public.team_members tm where tm.member_id=target or tm.team_id=any(managed) order by tm.team_id,tm.member_id for share;
 select coalesce(array_agg(distinct x),'{}'::uuid[]) into teams from (select unnest(managed) x union select tm.team_id from public.team_members tm where tm.member_id=target) q;
 perform 1 from public.teams t join public.divisions d on d.id=t.division_id join public.leagues l on l.id=d.league_id join public.seasons s on s.id=l.season_id where t.id=any(teams) order by t.id for share of t,d,l,s;
 -- Existing dashboards explicitly include target-linked inactive teams and previous seasons.
 perform 1 from public.matches m where m.home_team_id=any(managed) or m.away_team_id=any(managed) order by m.id for share;
 if not view_as_private.lock_authorization(p_proof,'identity') then raise exception 'View-As access denied';end if;
 return jsonb_build_object('memberId',target,'role',role_name,'teams',teams,'managed',managed);
end $fn$;
set local role lms_view_as_reader;
create or replace function lms_read_private.competition(p_viewer jsonb,p_contract text,p_args jsonb) returns jsonb language sql security invoker set search_path='' as $fn$ select jsonb_build_object('seasons',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'start_date',r.start_date,'end_date',r.end_date,'is_active',r.is_active,'abbreviation',r.abbreviation)),'[]'::jsonb) from public.seasons r where true),
'leagues',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'season_id',r.season_id,'name',r.name,'description',r.description,'is_active',r.is_active,'rosters_locked',r.rosters_locked,'league_document_bucket',r.league_document_bucket,'code_of_conduct_pdf_path',r.code_of_conduct_pdf_path,'captains_guide_pdf_path',r.captains_guide_pdf_path,'league_rules_pdf_path',r.league_rules_pdf_path,'score_sheet_pdf_path',r.score_sheet_pdf_path,'league_waiver_pdf_path',r.league_waiver_pdf_path,'match_setup_reminder_days_before',r.match_setup_reminder_days_before,'abbreviation',r.abbreviation,'flex_league',r.flex_league,'only_home_community_players',r.only_home_community_players)),'[]'::jsonb) from public.leagues r where true),
'divisions',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'league_id',r.league_id,'name',r.name,'skill_level',r.skill_level,'sort_order',r.sort_order,'is_active',r.is_active,'min_dupr',r.min_dupr,'max_dupr',r.max_dupr,'number_of_lines',r.number_of_lines,'default_game_format',r.default_game_format,'games_per_line',r.games_per_line,'points_to_win',r.points_to_win,'win_by',r.win_by,'third_game_format',r.third_game_format,'picklebreaker_enabled',r.picklebreaker_enabled,'picklebreaker_points',r.picklebreaker_points,'line_notes',r.line_notes,'rating_type',r.rating_type,'standings_win_points',r.standings_win_points,'standings_tie_points',r.standings_tie_points,'standings_loss_points',r.standings_loss_points,'standings_tiebreak_1',r.standings_tiebreak_1,'standings_tiebreak_2',r.standings_tiebreak_2,'standings_tiebreak_3',r.standings_tiebreak_3,'picklebreaker_win_points',r.picklebreaker_win_points,'picklebreaker_loss_points',r.picklebreaker_loss_points,'default_lines_config',r.default_lines_config,'team_dupr_max',r.team_dupr_max,'playoff_team_count',r.playoff_team_count,'score_sheet_template_id',r.score_sheet_template_id,'primary_team_type',r.primary_team_type,'secondary_number_of_lines',r.secondary_number_of_lines,'secondary_team_type',r.secondary_team_type,'flex_league',r.flex_league)),'[]'::jsonb) from public.divisions r where true),
'division_lines',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'division_id',r.division_id,'line_number',r.line_number,'line_name',r.line_name,'posted_to_dupr',r.posted_to_dupr,'game_format',r.game_format,'games_per_line',r.games_per_line,'points_to_win',r.points_to_win,'win_by',r.win_by,'picklebreaker_enabled',r.picklebreaker_enabled,'picklebreaker_points',r.picklebreaker_points,'line_type',r.line_type,'sort_order',r.sort_order,'picklebreaker_win_points',r.picklebreaker_win_points,'picklebreaker_loss_points',r.picklebreaker_loss_points,'team_win_points',r.team_win_points,'uses_saved_match_lineups',r.uses_saved_match_lineups,'standings_points_mode',r.standings_points_mode,'score_type',r.score_type,'score_required',r.score_required,'picklebreaker_not_played_points',r.picklebreaker_not_played_points,'picklebreaker_not_played_award_rule',r.picklebreaker_not_played_award_rule,'picklebreaker_play_rule',r.picklebreaker_play_rule)),'[]'::jsonb) from public.division_lines r where true),
'locations',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'address',r.address,'city',r.city,'state',r.state,'zip_code',r.zip_code,'number_of_courts',r.number_of_courts,'court_notes',r.court_notes,'club_pros',r.club_pros,'is_active',r.is_active,'club_pro_member_id',r.club_pro_member_id,'club_pro_2_member_id',r.club_pro_2_member_id)),'[]'::jsonb) from public.locations r where true),
'score_sheet_templates',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'description',r.description,'sheet_title',r.sheet_title,'template_html',r.template_html,'rules_text',r.rules_text,'is_default',r.is_default,'is_active',r.is_active)),'[]'::jsonb) from public.score_sheet_templates r where true),
'teams',(select coalesce(jsonb_agg(case when r.id in(select value::uuid from jsonb_array_elements_text(p_viewer->'teams')) then jsonb_build_object('id',r.id,'division_id',r.division_id,'name',r.name,'captain_member_id',r.captain_member_id,'co_captain_member_id',r.co_captain_member_id,'co_captain_2_member_id',r.co_captain_2_member_id,'club_pro_member_id',r.club_pro_member_id,'is_active',r.is_active,'home_location_id',r.home_location_id,'team_number',r.team_number,'notes',r.notes,'abbreviation',r.abbreviation) else jsonb_build_object('id',r.id,'name',r.name,'abbreviation',r.abbreviation,'division_id',r.division_id)||jsonb_build_object('is_active',r.is_active,'home_location_id',r.home_location_id) end),'[]'::jsonb) from public.teams r),
'matches',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'league_id',r.league_id,'division_id',r.division_id,'home_team_id',r.home_team_id,'away_team_id',r.away_team_id,'location_id',r.location_id,'scheduled_date',r.scheduled_date,'scheduled_time',r.scheduled_time,'week_number',r.week_number,'status',r.status,'home_score',r.home_score,'away_score',r.away_score,'published_at',r.published_at,'is_published',r.is_published,'schedule_setting_id',r.schedule_setting_id,'winning_team_id',r.winning_team_id,'score_status',r.score_status,'score_entered_at',r.score_entered_at,'score_verified_at',r.score_verified_at,'score_disputed',r.score_disputed,'finalized_at',r.finalized_at,'score_exported_at',r.score_exported_at,'result_type',r.result_type,'result_notes',r.result_notes)),'[]'::jsonb) from public.matches r where r.is_published is true),
'match_lines',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'match_id',r.match_id,'division_line_id',r.division_line_id,'line_number',r.line_number,'home_player_1_id',r.home_player_1_id,'home_player_2_id',r.home_player_2_id,'away_player_1_id',r.away_player_1_id,'away_player_2_id',r.away_player_2_id,'line_status',r.line_status,'home_wins',r.home_wins,'away_wins',r.away_wins,'posted_to_dupr',r.posted_to_dupr,'winning_team_id',r.winning_team_id,'verification_status',r.verification_status,'verified_by_member_id',r.verified_by_member_id,'verified_at',r.verified_at,'home_team_games_won',r.home_team_games_won,'away_team_games_won',r.away_team_games_won,'home_team_points',r.home_team_points,'away_team_points',r.away_team_points,'rating_type_at_play',r.rating_type_at_play,'home_player_1_rating_at_play',r.home_player_1_rating_at_play,'home_player_2_rating_at_play',r.home_player_2_rating_at_play,'away_player_1_rating_at_play',r.away_player_1_rating_at_play,'away_player_2_rating_at_play',r.away_player_2_rating_at_play,'home_team_rating_at_play',r.home_team_rating_at_play,'away_team_rating_at_play',r.away_team_rating_at_play,'ratings_snapshotted_at',r.ratings_snapshotted_at)),'[]'::jsonb) from public.match_lines r where exists(select 1 from public.matches m where m.id=r.match_id and m.is_published is true)),
'line_games',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'match_line_id',r.match_line_id,'game_number',r.game_number,'home_score',r.home_score,'away_score',r.away_score,'is_picklebreaker',r.is_picklebreaker,'game_status',r.game_status)),'[]'::jsonb) from public.line_games r where exists(select 1 from public.match_lines ml join public.matches m on m.id=ml.match_id where ml.id=r.match_line_id and m.is_published is true)),
'match_lineups',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'match_id',r.match_id,'team_id',r.team_id,'line_number',r.line_number,'player_1_member_id',r.player_1_member_id,'player_2_member_id',r.player_2_member_id)),'[]'::jsonb) from public.match_lineups r where r.team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'managed')) and exists(select 1 from public.matches m where m.id=r.match_id and m.is_published is true)),
'team_byes',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'league_id',r.league_id,'division_id',r.division_id,'team_id',r.team_id,'week_number',r.week_number,'bye_date',r.bye_date)),'[]'::jsonb) from public.team_byes r where true),
'team_standings',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'league_id',r.league_id,'division_id',r.division_id,'team_id',r.team_id,'matches_played',r.matches_played,'match_wins',r.match_wins,'match_losses',r.match_losses,'match_ties',r.match_ties,'line_wins',r.line_wins,'line_losses',r.line_losses,'line_ties',r.line_ties,'game_wins',r.game_wins,'game_losses',r.game_losses,'points_for',r.points_for,'points_against',r.points_against,'point_differential',r.point_differential,'standings_points',r.standings_points,'rank',r.rank,'home_wins',r.home_wins,'home_losses',r.home_losses,'away_wins',r.away_wins,'away_losses',r.away_losses,'current_streak',r.current_streak,'recent_form',r.recent_form,'finalized',r.finalized)),'[]'::jsonb) from public.team_standings r where true),
'match_setup_counts',(select coalesce(jsonb_agg(jsonb_build_object('match_id',x.match_id,'team_id',x.team_id,'completed',x.completed)),'[]'::jsonb) from (select ml.match_id,ml.team_id,count(*) filter(where ml.player_1_member_id is not null and ml.player_2_member_id is not null) completed from public.match_lineups ml join public.matches m on m.id=ml.match_id where m.is_published is true and (m.home_team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'managed')) or m.away_team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'managed'))) group by ml.match_id,ml.team_id) x),
'notification_templates',(select coalesce(jsonb_agg(jsonb_build_object('template_key',r.template_key,'body',r.body)),'[]'::jsonb) from public.notification_templates r where r.template_key='player_guide_pdf' or (r.template_key='captain_guide_pdf' and p_viewer->>'role' in('captain','club_pro','league_manager','commissioner')) or (r.template_key='admin_guide_pdf' and p_viewer->>'role' in('league_manager','commissioner')))); $fn$;
create or replace function lms_read_private.people(p_viewer jsonb,p_contract text,p_args jsonb) returns jsonb language sql security invoker set search_path='' as $fn$ select jsonb_build_object('members',(select coalesce(jsonb_agg(case when r.id=(p_viewer->>'memberId')::uuid then jsonb_build_object('id',r.id,'first_name',r.first_name,'last_name',r.last_name,'email',r.email,'phone',r.phone,'club_location',r.club_location,'dupr_id',r.dupr_id,'renewal_date',r.renewal_date,'is_active_member',r.is_active_member,'self_rating',r.self_rating,'profile_image_urls',r.profile_image_urls,'notification_preference',r.notification_preference) when exists(select 1 from public.team_members tm where tm.member_id=r.id and tm.team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'managed'))) then jsonb_build_object('id',r.id,'first_name',r.first_name,'last_name',r.last_name,'email',r.email,'phone',r.phone,'dupr_id',r.dupr_id,'self_rating',r.self_rating,'club_location',r.club_location,'is_active_member',r.is_active_member,'membership_status',r.membership_status,'renewal_date',r.renewal_date,'location_id',r.location_id) when exists(select 1 from public.teams t where t.id in(select value::uuid from jsonb_array_elements_text(p_viewer->'teams')) and r.id in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id,t.club_pro_member_id)) then jsonb_build_object('id',r.id,'first_name',r.first_name,'last_name',r.last_name,'full_name',r.full_name)||jsonb_build_object('email',r.email,'phone',r.phone) else jsonb_build_object('id',r.id,'first_name',r.first_name,'last_name',r.last_name,'full_name',r.full_name) end),'[]'::jsonb) from public.members r where r.id=(p_viewer->>'memberId')::uuid or exists(select 1 from public.teams t where t.id in(select value::uuid from jsonb_array_elements_text(p_viewer->'teams')) and r.id in(t.captain_member_id,t.co_captain_member_id,t.co_captain_2_member_id,t.club_pro_member_id)) or exists(select 1 from public.team_members tm where tm.member_id=r.id and tm.team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'teams'))) or exists(select 1 from public.match_lines ml join public.matches m on m.id=ml.match_id where m.is_published is true and r.id in(ml.home_player_1_id,ml.home_player_2_id,ml.away_player_1_id,ml.away_player_2_id))),'team_members',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'team_id',r.team_id,'member_id',r.member_id,'role',r.role,'is_active',r.is_active)),'[]'::jsonb) from public.team_members r where r.team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'teams'))),'member_season_ratings',(select coalesce(jsonb_agg(jsonb_build_object('member_id',r.member_id,'season_id',r.season_id,'season_dupr_rating',r.season_dupr_rating,'season_primetime_rating',r.season_primetime_rating,'dupr_doubles_rating',r.dupr_doubles_rating)),'[]'::jsonb) from public.member_season_ratings r where r.member_id=(p_viewer->>'memberId')::uuid or exists(select 1 from public.team_members tm join public.teams t on t.id=tm.team_id join public.divisions d on d.id=t.division_id join public.leagues l on l.id=d.league_id where tm.member_id=r.member_id and l.season_id=r.season_id and tm.team_id in(select value::uuid from jsonb_array_elements_text(p_viewer->'teams')))),'user_roles',(select coalesce(jsonb_agg(jsonb_build_object('member_id',r.member_id,'role',r.role)),'[]'::jsonb) from public.user_roles r where r.member_id=(p_viewer->>'memberId')::uuid),'system_settings',(select coalesce(jsonb_agg(jsonb_build_object('setting_key',r.setting_key,'setting_value',r.setting_value)),'[]'::jsonb) from public.system_settings r where r.setting_key in('club_name','club_short_name','system_name','browser_tab_title','logo_url','main_email','support_email','club_website','membership_url','league_site_url','timezone','email_activated'))); $fn$;
create or replace function view_as_private.page_read(p_proof jsonb,p_contract text,p_args jsonb) returns jsonb language plpgsql security definer set search_path='' as $fn$
declare v jsonb; result jsonb;
begin
 v:=lms_read_private.lock_viewer(p_proof,p_contract,p_args);
 result:=lms_read_private.competition(v,p_contract,p_args)||lms_read_private.people(v,p_contract,p_args);
 perform lms_read_private.lock_viewer(p_proof,p_contract,p_args);
 return jsonb_build_object('viewer',v,'tables',result);
end $fn$;
reset role;
revoke all on function lms_read_private.lock_viewer(jsonb,text,jsonb) from public,anon,authenticated,service_role,lms_view_as_executor;
set local role lms_view_as_reader;
revoke all on function lms_read_private.competition(jsonb,text,jsonb) from public,anon,authenticated,service_role,lms_view_as_executor;
alter function lms_read_private.competition(jsonb,text,jsonb) owner to lms_view_as_reader;
revoke all on function lms_read_private.people(jsonb,text,jsonb) from public,anon,authenticated,service_role,lms_view_as_executor;
alter function lms_read_private.people(jsonb,text,jsonb) owner to lms_view_as_reader;
revoke all on function view_as_private.page_read(jsonb,text,jsonb) from public,anon,authenticated,service_role,lms_view_as_executor;
alter function view_as_private.page_read(jsonb,text,jsonb) owner to lms_view_as_reader;
reset role;
grant execute on function lms_read_private.lock_viewer(jsonb,text,jsonb) to lms_view_as_reader;
set local role lms_view_as_reader;
grant execute on function view_as_private.page_read(jsonb,text,jsonb) to lms_view_as_executor;
reset role;
revoke create on schema lms_read_private,view_as_private from lms_view_as_reader;
revoke lms_view_as_reader from postgres granted by postgres;
grant create on schema public to lms_view_as_executor;
set local role lms_view_as_executor;
create or replace function public.lms_view_as(p_op text,p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $corrected$
declare c view_as_private.contexts; actor_member uuid; actor_role text; target_role text; target uuid;
 result jsonb; actor_name text; target_name text;
begin
 if octet_length(p_input::text)>32000 then return jsonb_build_object('denied',true);end if;
 if p_op='can_start' then return jsonb_build_object('allowed',coalesce(view_as_private.member_role(view_as_private.actor_member((p_input->>'actor')::uuid)) in('commissioner','league_manager'),false));end if;
 if p_op='preflight' then
  actor_role:=view_as_private.member_role(view_as_private.actor_member((p_input->>'actor')::uuid));
  target:=(p_input->>'target')::uuid;target_role:=view_as_private.member_role(target);
  if actor_role is null or actor_role not in('commissioner','league_manager') or target_role is null then return jsonb_build_object('allowed',false);end if;
  select concat_ws(' ',first_name,last_name) into target_name from public.members where id=target;
  return jsonb_build_object('allowed',true,'name',target_name);
 end if;
 if p_op='start' then
  actor_member:=view_as_private.actor_member((p_input->>'actor')::uuid);
  actor_role:=view_as_private.member_role(actor_member);target:=(p_input->>'target')::uuid;
  target_role:=view_as_private.member_role(target);
  if actor_role is null or actor_role not in('commissioner','league_manager') or target_role is null then
   return jsonb_build_object('denied',true,'message','This member does not yet have enough LMS account information to simulate their signed-in experience.'); end if;
  perform pg_advisory_xact_lock(hashtextextended(p_input->>'actor',724));
  if (select count(*) from view_as_private.contexts where actor=(p_input->>'actor')::uuid and created_at>clock_timestamp()-interval '1 minute')>=5
    or (select count(*) from view_as_private.contexts where actor=(p_input->>'actor')::uuid and created_at>clock_timestamp()-interval '1 hour')>=30
    then return jsonb_build_object('denied',true);end if;
  if (p_input->>'expires')::timestamptz<=clock_timestamp() or length(p_input->>'credential')>25000 then return jsonb_build_object('denied',true);end if;
  insert into view_as_private.contexts(id,actor,target,binding,browser,code,credential,expires_at)
  values((p_input->>'id')::uuid,(p_input->>'actor')::uuid,target,p_input->>'binding',p_input->>'browser',p_input->>'code',p_input->>'credential',least((p_input->>'expires')::timestamptz,clock_timestamp()+interval '30 minutes')) returning * into c;
  return jsonb_build_object('expires',c.expires_at);
 end if;
 if p_op='load_handoff' then select * into c from view_as_private.contexts where code=p_input->>'code' and browser=p_input->>'browser' and started_at is null for update;
 elsif p_op='load' then select * into c from view_as_private.contexts where context=p_input->>'context' and browser=p_input->>'browser' and started_at is not null for update;
 else select * into c from view_as_private.contexts where id=(p_input->>'id')::uuid and actor=(p_input->>'actor')::uuid and browser=p_input->>'browser' for update;
 end if;
 if c.id is null or c.ended_at is not null then return jsonb_build_object('denied',true);end if;
 if c.expires_at<=clock_timestamp() then perform view_as_private.end_context(c.id,'expiration');return jsonb_build_object('denied',true,'message','View As User session expired.');end if;
 if not view_as_private.lock_authorization(p_input,'identity') then return jsonb_build_object('denied',true);end if;
 actor_member:=view_as_private.actor_member(c.actor);actor_role:=view_as_private.member_role(actor_member);target_role:=view_as_private.member_role(c.target);
 if actor_role is null or actor_role not in('commissioner','league_manager') or target_role is null then
  perform view_as_private.end_context(c.id,case when target_role is null then 'target_invalidation' else 'authorization_loss' end);
  return jsonb_build_object('denied',true);end if;
 if p_op in('load','load_handoff') then
  if p_op='load_handoff' and c.exchange_by<=clock_timestamp() then perform view_as_private.end_context(c.id,'handoff_expiration');return jsonb_build_object('denied',true);end if;
  return jsonb_build_object('id',c.id,'actor',c.actor,'binding',c.binding,'credential',c.credential);
 end if;
 if p_op='exchange' then
  if c.code is distinct from p_input->>'code' or c.started_at is not null or c.exchange_by<=clock_timestamp() then return jsonb_build_object('denied',true);end if;
  update view_as_private.contexts set code=null,context=p_input->>'context',started_at=clock_timestamp() where id=c.id returning * into c;
  insert into view_as_private.audit_events(context_id,actor,effective_member,event,actor_role,effective_role)
  values(c.id,c.actor,c.target,'VIEW_AS_STARTED',actor_role,target_role);
 elsif c.context is distinct from p_input->>'context' or c.started_at is null then return jsonb_build_object('denied',true);
 end if;
 if p_op='end' then perform view_as_private.end_context(c.id,'explicit_exit');return jsonb_build_object('ended',true);end if;
 if p_op='reserve_document' then
  perform pg_advisory_xact_lock(hashtextextended(c.actor::text,724));
  if (select count(*) from view_as_private.attempts where actor=c.actor and at>clock_timestamp()-interval '1 minute')>=10
   or (select count(*) from view_as_private.attempts where actor=c.actor and at>clock_timestamp()-interval '1 day')>=100 then return jsonb_build_object('rate_limited',true);end if;
  insert into view_as_private.attempts(actor,contact) values(c.actor,false);return jsonb_build_object('allowed',true);
 end if;
 if p_op='page_read' then return view_as_private.page_read(p_input||jsonb_build_object('target',c.target),p_input->>'contract',p_input->'args');end if;
 if p_op='snapshot' then return view_as_private.snapshot(c.target,target_role);end if;
 if p_op='live' then
  result:=view_as_private.lookup(c.actor,c.target,c.id,(p_input->>'request')::uuid,(p_input->'query')||jsonb_build_object('_view_proof',(p_input-'query')||jsonb_build_object('target',c.target,'intent',p_input->'query'->>'intent')));
  if result->>'status' in('denied','not_found','rate_limited') then
   insert into view_as_private.audit_events(context_id,actor,effective_member,event,capability,reason) values(c.id,c.actor,c.target,'READ_DENIED',p_input->'query'->>'intent',result->>'status');
  end if;
  return result;
 end if;
 if p_op='diagnostic' then
  if p_input->>'family' not in('document','LIVE_LMS_DATA') or p_input->>'kind' not in('answer','clarification','protected','insufficient_evidence','conflict','technical_error') then return jsonb_build_object('denied',true);end if;
  insert into view_as_private.diagnostic_outcomes(id,context_id,family,kind,total_ms) values((p_input->>'request')::uuid,c.id,p_input->>'family',p_input->>'kind',least(greatest((p_input->>'total_ms')::int,0),600000));
  return jsonb_build_object('recorded',true);
 end if;
 if p_op not in('resolve','exchange') then return jsonb_build_object('denied',true);end if;
 select concat_ws(' ',first_name,last_name) into actor_name from public.members where id=actor_member;
 select concat_ws(' ',first_name,last_name) into target_name from public.members where id=c.target;
 return jsonb_build_object('mode','VIEW_AS_READ_ONLY','readOnly',true,'actorName',actor_name,'actorRole',actor_role,
 'targetName',target_name,'role',target_role,'roles',(select jsonb_agg(distinct role) from public.user_roles where member_id=c.target),
 'hasAuth',(select exists(select 1 from public.user_roles where member_id=c.target and user_id is not null)),
 'expires',c.expires_at,'returnPath','/members/'||c.target::text);
end $corrected$;
reset role;
revoke create on schema public from lms_view_as_executor;
commit;
